export function isClipboardSupported() {
    return typeof navigator !== 'undefined' && !!navigator.clipboard;
}
export async function hasClipboardPermission(command) {
    if (typeof navigator !== 'undefined' && navigator.permissions && typeof navigator.permissions.query === 'function') {
        try {
            const permissionStatus = await navigator.permissions.query({ name: command });
            return permissionStatus.state === 'granted';
        }
        catch (error) {
            return true;
        }
    }
    return true;
}
export async function copyToClipboard(text) {
    if (isClipboardSupported()) {
        try {
            await navigator.clipboard.writeText(text);
            return true;
        }
        catch (error) {
            console.warn("navigator.clipboard.writeText failed, falling back to execCommand:", error);
            return commandCopy(text);
        }
    }
    else {
        return commandCopy(text);
    }
}
export async function pasteFromClipboard() {
    try {
        if (isClipboardSupported() && typeof navigator.clipboard.readText === 'function') {
            return await navigator.clipboard.readText();
        }
        return null;
    }
    catch (error) {
        console.error("Error pasting from clipboard:", error);
        return null;
    }
}
export async function copyHtmlToClipboard(html, plainText) {
    const textFallback = plainText ?? stripHtml(html);
    try {
        if (!isClipboardSupported() || typeof ClipboardItem === 'undefined') {
            return copyToClipboard(textFallback);
        }
        const htmlBlob = new Blob([html], { type: 'text/html' });
        const textBlob = new Blob([textFallback], { type: 'text/plain' });
        const item = new ClipboardItem({
            'text/html': htmlBlob,
            'text/plain': textBlob
        });
        await navigator.clipboard.write([item]);
        return true;
    }
    catch (error) {
        console.warn("copyHtmlToClipboard failed, falling back to plain text:", error);
        return copyToClipboard(textFallback);
    }
}
export async function readHtmlFromClipboard() {
    try {
        if (!isClipboardSupported() || typeof navigator.clipboard.read !== 'function') {
            return null;
        }
        const clipboardItems = await navigator.clipboard.read();
        for (const item of clipboardItems) {
            if (item.types.includes('text/html')) {
                const blob = await item.getType('text/html');
                return await blob.text();
            }
        }
        return null;
    }
    catch (error) {
        console.error("Error reading HTML from clipboard:", error);
        return null;
    }
}
export async function copyDataToClipboard(data, mimeType) {
    try {
        if (!isClipboardSupported() || typeof ClipboardItem === 'undefined') {
            console.warn("ClipboardItem is not supported in this browser.");
            return false;
        }
        const blob = new Blob([data], { type: mimeType });
        await navigator.clipboard.write([new ClipboardItem({ [mimeType]: blob })]);
        return true;
    }
    catch (error) {
        console.error("Error copying data to clipboard:", error);
        return false;
    }
}
export async function readDataFromClipboard(mimeType) {
    try {
        if (!isClipboardSupported() || typeof navigator.clipboard.read !== 'function') {
            return null;
        }
        const clipboardItems = await navigator.clipboard.read();
        for (const item of clipboardItems) {
            for (const type of item.types) {
                if (type === mimeType) {
                    const blob = await item.getType(type);
                    if (blob instanceof Blob) {
                        const arrayBuffer = await blob.arrayBuffer();
                        return new Uint8Array(arrayBuffer);
                    }
                }
            }
        }
        return null;
    }
    catch (error) {
        console.error("Error reading data from clipboard:", error);
        return null;
    }
}
export async function attachClipboardAction(targetId, action, dotNet) {
    const targetElement = document.getElementById(targetId);
    if (!targetElement) {
        await dotNet.invokeMethodAsync('OnTextActionCallback', "", action, false);
        return;
    }
    if (!isTextContentElement(targetElement)) {
        await dotNet.invokeMethodAsync('OnTextActionCallback', "", action, false);
        return;
    }
    const value = getElementContent(targetElement);
    const success = await copyToClipboard(value);
    if (success && action === 'cut') {
        clearElementContent(targetElement);
    }
    await dotNet.invokeMethodAsync('OnTextActionCallback', value, action, success);
}
const pasteZoneListeners = new Map();
export function initializePasteZone(elementId, dotNet) {
    const el = document.getElementById(elementId);
    if (!el)
        return;
    disposePasteZone(elementId);
    const onDrop = async (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length > 0) {
            const file = e.dataTransfer.files[0];
            const buffer = await file.arrayBuffer();
            const bytes = new Uint8Array(buffer);
            await dotNet.invokeMethodAsync('OnDropCallback', bytes, file.type, file.name);
        }
        else if (e.dataTransfer) {
            const text = e.dataTransfer.getData('text/plain');
            const html = e.dataTransfer.getData('text/html');
            if (text || html) {
                await dotNet.invokeMethodAsync('OnDropTextCallback', text, html);
            }
        }
    };
    const onDragOver = (e) => {
        e.preventDefault();
        e.stopPropagation();
    };
    el.addEventListener('drop', onDrop);
    el.addEventListener('dragover', onDragOver);
    pasteZoneListeners.set(elementId, { onDrop, onDragOver });
}
export function disposePasteZone(elementId) {
    const el = document.getElementById(elementId);
    const listeners = pasteZoneListeners.get(elementId);
    if (el && listeners) {
        el.removeEventListener('drop', listeners.onDrop);
        el.removeEventListener('dragover', listeners.onDragOver);
    }
    pasteZoneListeners.delete(elementId);
}
function getElementContent(element) {
    if (element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement) {
        return element.value;
    }
    else {
        return element.innerText;
    }
}
function clearElementContent(element) {
    if (element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement) {
        element.value = '';
    }
    else if (element.isContentEditable) {
        element.innerText = '';
    }
    else {
        element.innerText = '';
    }
}
function isTextContentElement(element) {
    return (element instanceof HTMLInputElement ||
        element instanceof HTMLTextAreaElement ||
        element.isContentEditable ||
        element instanceof HTMLHeadingElement ||
        element instanceof HTMLParagraphElement ||
        element instanceof HTMLSpanElement ||
        element instanceof HTMLDivElement);
}
function stripHtml(html) {
    if (typeof document !== 'undefined') {
        const div = document.createElement('div');
        div.innerHTML = html;
        return div.textContent || div.innerText || '';
    }
    return html.replace(/<[^>]*>?/gm, '');
}
function commandCopy(value) {
    try {
        const ta = document.createElement('textarea');
        ta.value = value ?? '';
        ta.style.position = 'fixed';
        ta.style.left = '-9999px';
        ta.style.top = '-9999px';
        ta.style.opacity = '0';
        ta.setAttribute('readonly', '');
        document.body.appendChild(ta);
        ta.focus();
        ta.select();
        const successful = document.execCommand('copy');
        document.body.removeChild(ta);
        return successful;
    }
    catch (err) {
        console.error("execCommand copy fallback failed:", err);
        return false;
    }
}
